    private static AnimationDefinition gait(float length, float stride, float lift, float bob) {
        return AnimationDefinition.Builder.withLength(length).looping()
            .addAnimation("foot_left", new AnimationChannel(AnimationChannel.Targets.ROTATION,
                new Keyframe(0F, KeyframeAnimations.degreeVec(-stride, 0, 0), AnimationChannel.Interpolations.LINEAR),
                new Keyframe(length / 2, KeyframeAnimations.degreeVec(stride, 0, 0), AnimationChannel.Interpolations.LINEAR),
                new Keyframe(length, KeyframeAnimations.degreeVec(-stride, 0, 0), AnimationChannel.Interpolations.LINEAR)))
            .addAnimation("foot_right", new AnimationChannel(AnimationChannel.Targets.ROTATION,
                new Keyframe(0F, KeyframeAnimations.degreeVec(stride, 0, 0), AnimationChannel.Interpolations.LINEAR),
                new Keyframe(length / 2, KeyframeAnimations.degreeVec(-stride, 0, 0), AnimationChannel.Interpolations.LINEAR),
                new Keyframe(length, KeyframeAnimations.degreeVec(stride, 0, 0), AnimationChannel.Interpolations.LINEAR)))
            .addAnimation("body", new AnimationChannel(AnimationChannel.Targets.POSITION,
                new Keyframe(0F, KeyframeAnimations.posVec(0, 0, 0), AnimationChannel.Interpolations.LINEAR),
                new Keyframe(length / 2, KeyframeAnimations.posVec(0, bob, 0), AnimationChannel.Interpolations.LINEAR),
                new Keyframe(length, KeyframeAnimations.posVec(0, 0, 0), AnimationChannel.Interpolations.LINEAR)))
            .addAnimation("wing_left", new AnimationChannel(AnimationChannel.Targets.ROTATION,
                new Keyframe(0F, KeyframeAnimations.degreeVec(0, -10, -65), AnimationChannel.Interpolations.LINEAR),
                new Keyframe(length, KeyframeAnimations.degreeVec(0, -10, -65), AnimationChannel.Interpolations.LINEAR)))
            .addAnimation("wing_right", new AnimationChannel(AnimationChannel.Targets.ROTATION,
                new Keyframe(0F, KeyframeAnimations.degreeVec(0, 10, 65), AnimationChannel.Interpolations.LINEAR),
                new Keyframe(length, KeyframeAnimations.degreeVec(0, 10, 65), AnimationChannel.Interpolations.LINEAR)))
            .addAnimation("wingtip_left", new AnimationChannel(AnimationChannel.Targets.ROTATION,
                new Keyframe(0F, KeyframeAnimations.degreeVec(0, -35, 95), AnimationChannel.Interpolations.LINEAR),
                new Keyframe(length, KeyframeAnimations.degreeVec(0, -35, 95), AnimationChannel.Interpolations.LINEAR)))
            .addAnimation("wingtip_right", new AnimationChannel(AnimationChannel.Targets.ROTATION,
                new Keyframe(0F, KeyframeAnimations.degreeVec(0, 35, -95), AnimationChannel.Interpolations.LINEAR),
                new Keyframe(length, KeyframeAnimations.degreeVec(0, 35, -95), AnimationChannel.Interpolations.LINEAR)))
            .build();
    }
    public static final AnimationDefinition WALK = gait(.8F, 12F, 0F, .08F);
    public static final AnimationDefinition RUN = gait(.45F, 19F, 0F, .18F);

// OPTIONAL PORT subtle idle; static source rest stays rest if desired.
    public static final AnimationDefinition IDLE_BREATHE = AnimationDefinition.Builder.withLength(2.0F).looping()
        .addAnimation("body", new AnimationChannel(AnimationChannel.Targets.POSITION, new Keyframe(0.0F, KeyframeAnimations.posVec(0.0F, 0.0F, 0.0F), AnimationChannel.Interpolations.LINEAR), new Keyframe(1.0F, KeyframeAnimations.posVec(-0.0F, 0.05F, 0.0F), AnimationChannel.Interpolations.LINEAR), new Keyframe(2.0F, KeyframeAnimations.posVec(0.0F, 0.0F, 0.0F), AnimationChannel.Interpolations.LINEAR)))
        .build();

